INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (4, 'Os Farofeiros 3', 'Roberto Santucci', '2026-11-05', 'Rocha decide bancar o casamento da filha em uma ilha paradisíaca no Caribe e convida seus amigos e suas famílias para uma viagem repleta de confusões.', 'https://br.web.img2.acsta.net/c_310_420/img/8d/67/8d678810bdcee027f560c8cbdd844c5f.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (5, 'Ebenezer e os Fantasmas do Natal', 'Ti West', '2026-11-12', 'Na véspera de Natal, Ebenezer Scrooge recebe a visita de fantasmas que o fazem confrontar suas escolhas e refletir sobre a possibilidade de mudar seu destino.', 'https://br.web.img3.acsta.net/c_310_420/img/41/5a/415aecd9d5238491c9c7c119c27a914a.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (6, 'O Gatola da Cartola', 'Alessandro Carloni e Erica Rivinoja', '2026-11-05', 'O Gatola precisa alegrar dois irmãos que enfrentam dificuldades para se adaptar à nova cidade. Sua missão acaba se transformando em uma aventura cheia de confusões.', 'https://br.web.img3.acsta.net/c_310_420/img/84/52/8452af129e93e1e82a23c5e88f3caa4d.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (7, 'Godzilla Minus Zero', 'Takashi Yamazaki', '2026-11-05', 'Dois anos após os acontecimentos de Godzilla Minus One, o Japão tenta se reconstruir, mas uma nova ameaça colossal coloca novamente a humanidade em perigo.', 'https://br.web.img3.acsta.net/c_310_420/img/62/c4/62c45d6c1236346b47b5b2e9e124363e.png');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (8, 'A Virada: Ignição da Alma', 'Alessandro Barros', '2026-11-12', 'Noah Silva utiliza métodos antiéticos para vender carros usados no Rio de Janeiro, mas suas escolhas acabam provocando consequências em sua vida pessoal e profissional.', 'https://br.web.img3.acsta.net/c_310_420/img/3e/db/3edbc651e8bd80f6d973b7c36bbd77fe.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (9, 'Como Roubar um Banco', 'David Leitch', '2026-09-03', 'Um ladrão ambicioso transforma seus assaltos a bancos em verdadeiros espetáculos virais, atraindo atenção e complicações cada vez maiores.', 'https://br.web.img3.acsta.net/c_310_420/img/95/e2/95e21af7d12039433b3a75f1013ac724.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (10, 'O Bosque Selvagem', 'Travis Knight', '2026-10-22', 'Uma jovem é levada às profundezas de uma floresta encantada para tentar salvar seu irmão mais novo de criaturas misteriosas.', 'https://br.web.img2.acsta.net/c_310_420/img/9b/83/9b836af29d0d1dd86234d9b18a5b76a3.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (11, 'Feito Pipa', 'Allan Deberton', '2026-11-05', 'Gugu é um menino que tenta esconder o avanço do Alzheimer de sua avó, com medo de ser obrigado a morar com seu pai, com quem tem uma relação difícil.', 'https://br.web.img3.acsta.net/c_310_420/img/b2/31/b231322fc6bccb09027ea42d9affc5cb.png');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (2, 'Jogos Vorazes: Amanhecer na Colheita', 'Francis Lawrence', '2026-11-19', 'A história acompanha Haymitch Abernathy durante o Segundo Massacre Quaternário, os 50º Jogos Vorazes. Ele precisa enfrentar uma arena mortal e desafiar as regras da Capital.', 'https://br.web.img3.acsta.net/c_310_420/img/35/49/3549fb00e12afe6566525b2e7777ce5a.jpg');
INSERT INTO public.filme (id, titulo, diretor, dt_lancamento, sinopse, capa_filme) VALUES (3, 'Eu Sou o Rocky', 'Peter Farrelly', '2026-11-19', 'A história mostra a trajetória de Sylvester Stallone e sua determinação para conseguir interpretar Rocky Balboa no filme que mudaria sua carreira.', 'https://br.web.img3.acsta.net/c_310_420/img/d7/90/d7903ee21d500ba076f74de65c6e8104.png');
